To solve this problem, we will use matrix exponentiation by squaring. This method allows us to efficiently compute large powers of a matrix while reducing each entry modulo 987489.

Let's implement the algorithm in Python:

```python
def matrix_multiply(A, B, mod):
    n = len(A)
    C = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            for k in range(n):
                C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % mod
    return C

def matrix_power(matrix, power, mod):
    n = len(matrix)
    result = [[1 if i == j else 0 for j in range(n)] for i in range(n)]

    while power > 0:
        if power % 2 == 1:
            result = matrix_multiply(result, matrix, mod)
        matrix = matrix_multiply(matrix, matrix, mod)
        power //= 2

    return result

def solve(inputs: dict) -> float:
    M = inputs['M']
    power = inputs['power']
    mod = inputs['mod']

    M_37 = matrix_power(M, power, mod)
    total_sum = sum(sum(row) for row in M_37)
    return total_sum
